    sample_banner: "આ ઇન્વૉઇસ પર વેચનારનો નમૂનો બતાવ્યો છે. તમારા વેપારની વિગતો એક વાર ભરો, પછી દરેક દસ્તાવેજમાં એ જ આવશે.",
