    tip5: "ਪਹਿਲਾਂ ਕੋਟੇਸ਼ਨ ਭੇਜੋ, ਫਿਰ ਇੱਕ ਕਲਿੱਕ ਨਾਲ ਉਸ ਦਾ ਇਨਵੌਇਸ ਬਣਾਓ। ਗਾਹਕ ਭੁਗਤਾਨ ਕਰੇ ਤਾਂ \"ਭੁਗਤਾਨ ਦਰਜ ਕਰੋ\" ਨਾਲ ਰਸੀਦ ਬਣਾਓ।",
