    tip1: "\"ମୋ ବ୍ୟବସାୟ\" ଥରେ ଭରନ୍ତୁ: GSTIN, ଠିକଣା, ବ୍ୟାଙ୍କ, UPI ID, ଲୋଗୋ ଓ ଦସ୍ତଖତ। ପ୍ରତି ଡକ୍ୟୁମେଣ୍ଟରେ ଏଗୁଡିକ ଆସିବ।",
