    tip4: "\"ପ୍ରିଣ୍ଟ / PDF\" ଦବାଇ \"Save as PDF\" ବାଛନ୍ତୁ ଓ ଇନଭଏସ୍ ଇମେଲ୍ ବା WhatsApp ରେ ପଠାନ୍ତୁ। ସବୁ କପି ଏକାଥରେ ଛାପିବା ପାଇଁ ଦ୍ୱିତୀୟ ଓ ତୃତୀୟ କପିରେ ଟିକ୍ ଦିଅନ୍ତୁ।",
    tip5: "ପ୍ରଥମେ କୋଟେସନ୍ ପଠାନ୍ତୁ, ତା’ପରେ ଗୋଟିଏ କ୍ଲିକରେ ତାକୁ ଇନଭଏସ୍ କରନ୍ତୁ। ଗ୍ରାହକ ଟଙ୍କା ଦେଲେ \"ପେମେଣ୍ଟ ଲେଖନ୍ତୁ\" ଦ୍ୱାରା ରସିଦ ତିଆରି କରନ୍ତୁ।",
    tip6: "ମାସ ଶେଷରେ ଆକାଉଣ୍ଟାଣ୍ଟଙ୍କ ପାଇଁ ଇନଭଏସ୍ ରେଜିଷ୍ଟର (CSV) ଡାଉନଲୋଡ୍ କରନ୍ତୁ, ଆଉ ବ୍ୟାକଅପ୍ ଫାଇଲ୍ ସୁରକ୍ଷିତ ସ୍ଥାନରେ ରଖନ୍ତୁ।",
