    tip1: "\"என் வணிகம்\" பகுதியை ஒருமுறை நிரப்புங்கள்: GSTIN, முகவரி, வங்கி, UPI ID, லோகோ, கையொப்பம். ஒவ்வொரு ஆவணத்திலும் இவையே வரும்.",
    tip2: "வாடிக்கையாளரின் GSTIN-ஐ எழுதுங்கள் அல்லது மாநிலத்தைத் தேர்வு செய்யுங்கள். CGST + SGST (அதே மாநிலம்) அல்லது IGST (வேறு மாநிலம்) என்பதைச் செயலியே முடிவு செய்யும்.",
    tip3: "சேமித்த பொருளின் பெயரைத் தட்டச்சு செய்யத் தொடங்குங்கள்; அதன் HSN, அலகு, விலை, GST தானாக நிரம்பும். Enter அழுத்தினால் அளவுக்குப் போகும், மீண்டும் Enter அழுத்தினால் அடுத்த வரிசை.",
    tip4: "\"அச்சிடு / PDF\" அழுத்தி \"Save as PDF\" தேர்வு செய்து இன்வாய்ஸை மின்னஞ்சலிலோ WhatsApp-இலோ அனுப்புங்கள். எல்லா நகல்களையும் ஒன்றாக அச்சிட இரண்டாம், மூன்றாம் நகல்களைத் தேர்வு செய்யுங்கள்.",
    tip5: "முதலில் கொட்டேஷன் அனுப்புங்கள், பிறகு ஒரே கிளிக்கில் அதை இன்வாய்ஸ் ஆக்குங்கள். வாடிக்கையாளர் பணம் தந்ததும் \"பணம் பதிவு செய்\" மூலம் ரசீது உருவாக்குங்கள்.",
    tip6: "மாத இறுதியில் உங்கள் கணக்காளருக்காக இன்வாய்ஸ் பதிவேட்டை (CSV) பதிவிறக்குங்கள்; காப்புப்பிரதிக் கோப்பைப் பாதுகாப்பான இடத்தில் வையுங்கள்.",
